def _decimal(value: Any, field_name: str) -> Decimal:
    """Return a finite Decimal while rejecting bool and malformed input."""
    if isinstance(value, bool) or value is None:
        raise ManaPolicyError(f"{field_name} must be a finite number, not {value!r}")
    if isinstance(value, float) and not isfinite(value):
        raise ManaPolicyError(f"{field_name} must be finite")
    try:
        result = Decimal(str(value))
    except (InvalidOperation, ValueError, TypeError) as error:
        raise ManaPolicyError(f"{field_name} must be a finite number") from error
    if not result.is_finite():
        raise ManaPolicyError(f"{field_name} must be finite")
    return result

def _non_negative_decimal(value: Any, field_name: str) -> Decimal:
    result = _decimal(value, field_name)
    if result < 0:
        raise ManaPolicyError(f"{field_name} must not be negative")
    return result

def _non_negative_int(value: Any, field_name: str) -> int:
    number = _non_negative_decimal(value, field_name)
    if number != number.to_integral_value():
        raise ManaPolicyError(f"{field_name} must be an integer")
    return int(number)

def round_mana_value(value: Any) -> int:
    """Round a non-negative Mana value with explicit half-up semantics."""
    number = _non_negative_decimal(value, "value")
    return int(number.quantize(Decimal("1"), rounding=ROUND_HALF_UP))

def validate_mana_skill_definition(skill: Mapping[str, Any]) -> dict[str, Decimal]:
    """Validate and normalize the future hybrid-cost contract of one Mana skill."""
    if not isinstance(skill, Mapping):
        raise ManaPolicyError("skill must be a mapping")
    if str(skill.get("cost_type") or "") != "mana":
        raise ManaPolicyError("skill cost_type must be 'mana'")
    missing = [
        field for field in (MANA_COST_FLAT_FIELD, MANA_COST_MAX_MP_PERCENT_FIELD)
        if field not in skill
    ]
    if missing:
        raise ManaPolicyError("missing Mana cost fields: " + ", ".join(missing))
    normalized = {
        MANA_COST_FLAT_FIELD: _non_negative_decimal(
            skill[MANA_COST_FLAT_FIELD], MANA_COST_FLAT_FIELD
        ),
        MANA_COST_MAX_MP_PERCENT_FIELD: _non_negative_decimal(
            skill[MANA_COST_MAX_MP_PERCENT_FIELD], MANA_COST_MAX_MP_PERCENT_FIELD
        ),
    }
    if MANA_RESTORE_MAX_MP_PERCENT_FIELD in skill:
        normalized[MANA_RESTORE_MAX_MP_PERCENT_FIELD] = _non_negative_decimal(
            skill[MANA_RESTORE_MAX_MP_PERCENT_FIELD],
            MANA_RESTORE_MAX_MP_PERCENT_FIELD,
        )
    return normalized

def calculate_mana_restore_amount(max_mp: Any, percent: Any) -> int:
    """Return a clamped nominal percentage restoration amount."""
    maximum = _non_negative_int(max_mp, "max_mp")
    restore_percent = _non_negative_decimal(percent, "percent")
    amount = round_mana_value(Decimal(maximum) * restore_percent / Decimal("100"))
    return min(maximum, amount)

def calculate_post_combat_mp_floor(
    max_mp: Any,
    percent: Any = MANA_POST_COMBAT_FLOOR_CURRENT_PERCENT,
) -> int:
    """Return the active canonical 50% post-combat Mana floor."""
    return calculate_mana_restore_amount(max_mp, percent)

def apply_post_combat_mp_floor_value(
    current_mp: Any,
    max_mp: Any,
    percent: Any = MANA_POST_COMBAT_FLOOR_CURRENT_PERCENT,
) -> int:
    """Apply a floor without adding it and without exceeding Max MP."""
    maximum = _non_negative_int(max_mp, "max_mp")
    current = min(_non_negative_int(current_mp, "current_mp"), maximum)
    return max(current, calculate_post_combat_mp_floor(maximum, percent))

def calculate_passive_mp_regen_per_full_minute(max_mp: Any) -> int:
    """Return the unchanged 30% per-full-minute passive regeneration tick."""
    return calculate_mana_restore_amount(max_mp, MANA_REGEN_PERCENT_PER_FULL_MINUTE)

def _number(value) -> float:
    try:
        result = float(value or 0)
    except (TypeError, ValueError):
        return 0.0
    return result

def calculate_max_hp(*, base_hp=0, stamina_hp=0, equipment_hp=0, refinement_hp=0) -> int:
    """Combine already-calculated HP components without redefining HP scaling."""
    return _whole_non_negative(
        _number(base_hp) + _number(stamina_hp) + _number(equipment_hp) + _number(refinement_hp)
    )

def _calculate_weighted_attack(character_class, matrix, *, strength=0, dexterity=0, intelligence=0, wisdom=0, stamina=0) -> int:
    class_key = str(character_class or "").strip().casefold()
    coefficients = matrix.get(class_key)
    if coefficients is None:
        return 0
    stats = {
        "str": _number(strength),
        "dex": _number(dexterity),
        "int": _number(intelligence),
        "wis": _number(wisdom),
        "sta": _number(stamina),
    }
    raw = sum(stats[key] * coefficients[key] for key in PRIMARY_STAT_KEYS)
    return max(1, int(raw))

def calculate_physical_defense(*, equipment_pdef=0, stamina=0) -> int:
    """Stage 18.14.2: active item PDEF plus total STA at coefficient 0.35."""
    from data.defense_policy import calculate_total_defense

    return int(calculate_total_defense(equipment_pdef, stamina))

def calculate_magical_defense(*, equipment_mdef=0, wisdom=0) -> int:
    """Stage 18.14.2: active item MDEF plus total WIS at coefficient 0.35."""
    from data.defense_policy import calculate_total_defense

    return int(calculate_total_defense(equipment_mdef, wisdom))

def calculate_max_mp(character_class, *, level=0, intelligence=0, wisdom=0) -> int:
    """Return configurable maximum mana for mana classes."""
    class_key = str(character_class or "").strip().casefold()
    if class_key not in MANA_CLASSES:
        return 0
    raw = (
        MAX_MP_SCALING["base"]
        + _number(level) * MAX_MP_SCALING["level"]
        + _number(intelligence) * MAX_MP_SCALING["int"]
        + _number(wisdom) * MAX_MP_SCALING["wis"]
    )
    return max(0, int(raw))

def _db():

    import db

    return db

def normalize_character_name(name):

    value = str(name or "").strip()

    value = unicodedata.normalize("NFC", value)

    return re.sub(r"\s+", " ", value)

def validate_character_name(name):

    value = normalize_character_name(name)

    if len(value) < NAME_MIN_LENGTH:

        return False, f"Ім’я має містити щонайменше {NAME_MIN_LENGTH} символи."

    if len(value) > NAME_MAX_LENGTH:

        return False, f"Ім’я має містити не більше {NAME_MAX_LENGTH} символів."

    if any(char in FORBIDDEN_NON_UKRAINIAN_CYRILLIC_LETTERS for char in value):

        return False, "Ім'я не повинно містити літери мови ворога."

    if not any(char.isalpha() for char in value):

        return False, "Ім’я має містити хоча б одну літеру."

    return True, ""

def is_character_name_taken(name, exclude_user_id=None):

    init_character_class_system()

    db = _db()

    normalized = normalize_character_name(name).casefold()

    db.cursor.execute("SELECT user_id, character_name FROM users WHERE TRIM(COALESCE(character_name, '')) <> ''")

    for user_id, existing in db.cursor.fetchall():

        if exclude_user_id is not None and int(user_id) == int(exclude_user_id):

            continue

        if normalize_character_name(existing).casefold() == normalized:

            return True

    return False

def get_character_name(user_id):

    init_character_class_system()

    db = _db()

    db.cursor.execute("SELECT character_name FROM users WHERE user_id=?", (user_id,))

    row = db.cursor.fetchone()

    return normalize_character_name(row[0] if row else "")

def set_character_name(user_id, name):

    init_character_class_system()

    db = _db()

    value = normalize_character_name(name)

    valid, message = validate_character_name(value)

    if not valid:

        return {"success": False, "message": f"❌ {message}"}

    if is_character_name_taken(value, exclude_user_id=user_id):

        return {"success": False, "message": "❌ Це ім’я вже зайняте іншим персонажем."}

    db.cursor.execute("UPDATE users SET character_name=? WHERE user_id=?", (value, user_id))

    db.conn.commit()

    return {"success": True, "message": "✅ Ім’я персонажа збережено.", "character_name": value}

